from collections import Counter
from math import ceil

def solve(grid):
    n = len(grid)
    m = len(grid[0]) if n else 0

    # ------------------------------------------------------------
    # 1. Find the T‑shaped colour (the "anchor")
    # ------------------------------------------------------------
    flat = [cell for row in grid for cell in row]
    cnt = Counter(flat)

    T_color = None
    T_row = T_col = None
    T_cols = []                     # columns of the T (three consecutive)

    for col, c in cnt.items():
        if c != 4:
            continue
        # collect positions
        pos = [(i, j) for i in range(n) for j in range(m) if grid[i][j] == col]
        rows = sorted({r for r, _ in pos})
        if len(rows) != 2:
            continue
        r1, r2 = rows
        cells_r1 = [c for (r, c) in pos if r == r1]
        cells_r2 = [c for (r, c) in pos if r == r2]
        if len(cells_r1) == 1 and len(cells_r2) == 3:
            single = cells_r1[0]
            triple = sorted(cells_r2)
            if triple == [single - 1, single, single + 1]:
                T_color = col
                T_row, T_col = r1, single
                T_cols = [T_col - 1, T_col, T_col + 1]
                break

    # ------------------------------------------------------------
    # 2. Find the colour directly above the T (the "to‑remove" colour)
    # ------------------------------------------------------------
    remove_color = 0
    if T_row > 0:
        remove_color = grid[T_row - 1][T_col]

    # columns where the remove colour appears (used for distance calculation)
    remove_cols = set()
    if remove_color:
        for i in range(n):
            for j in range(m):
                if grid[i][j] == remove_color:
                    remove_cols.add(j)

    # ------------------------------------------------------------
    # 3. Build empty output grid, copy the T shape unchanged
    # ------------------------------------------------------------
    out = [[0] * m for _ in range(n)]
    if T_color is not None:
        for i in range(n):
            for j in range(m):
                if grid[i][j] == T_color:
                    out[i][j] = T_color

    # ------------------------------------------------------------
    # 4. Process every other colour (except 0, T and remove)
    # ------------------------------------------------------------
    colours = set(cnt.keys()) - {0, T_color, remove_color}

    for col in colours:
        # ---- collect all clusters (horizontal runs) for this colour
        rows_with = set()
        clusters = []          # each element: (row, start, end, distance)
        for i in range(n):
            j = 0
            while j < m:
                if grid[i][j] == col:
                    start = j
                    while j + 1 < m and grid[i][j + 1] == col:
                        j += 1
                    end = j
                    # distance to nearest remove column
                    if remove_cols:
                        dist = min(abs(c - rc) for c in range(start, end + 1) for rc in remove_cols)
                    else:
                        dist = 0
                    clusters.append((i, start, end, dist))
                    rows_with.add(i)
                j += 1

        if not clusters:
            continue

        max_dist = max(c[3] for c in clusters)

        # ------------------- case A: max distance > 0 -------------------
        if max_dist > 0:
            # keep all clusters whose distance equals max_dist
            kept = [c for c in clusters if c[3] == max_dist]

            # rightmost cluster overall (largest start column)
            rightmost = max(clusters, key=lambda x: (x[1], x[2]))
            # does it overlap the T?
            overlaps = any(col in T_cols for col in range(rightmost[1], rightmost[2] + 1))
            if not overlaps and rightmost not in kept:
                kept.append(rightmost)

            # write kept clusters into the output
            for (r, s, e, _) in kept:
                for cc in range(s, e + 1):
                    out[r][cc] = col

        # ------------------- case B: max distance == 0 -------------------
        else:
            # keep only clusters in the top half of the rows that contain this colour
            sorted_rows = sorted(rows_with)
            half = (len(sorted_rows) + 1) // 2          # ceil
            top_rows = sorted_rows[:half]

            for r in top_rows:
                row_clusters = [c for c in clusters if c[0] == r]
                row_clusters.sort(key=lambda x: x[1])   # sort by start column

                if len(row_clusters) == 1:
                    keep_row = row_clusters
                else:
                    # special two‑cluster situation: left overlaps T, right does not
                    if len(row_clusters) == 2:
                        c1_s, c1_e = row_clusters[0][1], row_clusters[0][2]
                        c2_s, c2_e = row_clusters[1][1], row_clusters[1][2]
                        left_overlaps = any(col in T_cols for col in range(c1_s, c1_e + 1))
                        right_overlaps = any(col in T_cols for col in range(c2_s, c2_e + 1))
                        if left_overlaps and not right_overlaps:
                            keep_row = row_clusters          # keep both
                        else:
                            keep_row = [row_clusters[0]]      # keep only leftmost
                    else:
                        # three or more clusters → keep only the leftmost
                        keep_row = [row_clusters[0]]

                for (rr, ss, ee, _) in keep_row:
                    for cc in range(ss, ee + 1):
                        out[rr][cc] = col

